import React from "react";

/**
 * 4. Definición del Problema (PDF) -> models.Anamnesis.definicion_problema
 */
export default function DefinicionProblemaSection({ value, setValue, onSave }) {
  return (
    <section className="card">
      <div className="card-header">
        <h5>4. Definición del problema o situación que motiva la entrevista</h5>
        <button className="btn" onClick={onSave}>Guardar sección</button>
      </div>
      <div className="card-body">
        <textarea
          rows={6}
          value={value}
          onChange={(e) => setValue(e.target.value)}
          placeholder="Describa la situación que motiva la entrevista…"
        />
      </div>
    </section>
  );
}
